Certainly! Here's a simple Linked List implementation using Python:

```python
class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def is_empty(self):
        return self.head == None

    def insert_at_beginning(self, data):
        new_node = Node(data)
        if self.is_empty():
            self.head = new_node
        else:
            current = self.head
            while current.next != None:
                current = current.next
            current.next = new_node

    def insert_at_end(self, data):
        if self.is_empty():
            self.head = Node(data)
        else:
            current = self.head
            while current.next != None:
                current = current.next
            current.next = Node(data)

    def delete_at_beginning(self):
        if self.is_empty():
            return None
        current = self.head
        while current.next != None:
            current = current.next
        if current.next == self.head:
            self.head = None
        else:
            current.next = current.next.next

    def delete_at_end(self):
        if self.is_empty():
            return None
        current = self.head
        while current.next != None:
            current = current.next
        if current == self.head:
            self.head = None
        else:
            current.next = current.next.next

    def get_at_beginning(self):
        if self.is_empty():
            return None
        current = self.head
        while current.next != None:
            current = current.next
        return current.data

    def get_at_end(self):
        if self.is_empty():
            return None
        current = self.head
        while current.next != None:
            current = current.next
        return current.data

    def __str__(self):
        str_list = []
        current = self.head
        while current != None:
            str_list.append(current.data)
            current = current.next
        return "Linked List:\n" + "\n".join(str_list)
```

Here's how you can use this Linked List implementation to insert, delete, and get elements at different positions in the list:

```python
my_list = LinkedList()
my_list.insert_at_beginning(10)
print(my_list)  # Linked List: [10]

my_list.insert_at_end(20)
print(my_list)  # Linked List: [10, 20]

my_list.delete_at_beginning()
print(my_list)  # Linked List: []

my_list.get_at_beginning()
print(my_list)  # Linked List: [10]

my_list.get_at_end()
print(my_list)  # Linked List: []
```

Here's an example of a basic Binary Search Tree (BST) implementation in C++:

```cpp
#include <iostream>
using namespace std;

// Node structure for the BST
struct Node {
    int data;
    Node* left;
    Node* right;
};

// Function to create a new node
Node* createNode(int data) {
    Node* newNode = new Node();
    if (!newNode) {
        cout << "Memory error\n";
        return NULL;
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a node into the BST
void insert(Node** root, int data) {
    if (*root == NULL) {
        *root = createNode(data);
        return;
    }

    if (data < (*root)->data)
        insert(&((*root)->left), data);
    else if (data > (*root)->data)
        insert(&((*root)->right), data);
}

// Function to search for a node in the BST
bool search(Node* root, int data) {
    if (root == NULL || root->data == data)
        return true;
    if (data < root->data)
        return search(root->left, data);
    return search(root->right, data);
}

// Function to print the inorder traversal of the BST
void printInorder(Node* root) {
    if (root != NULL) {
        printInorder(root->left);
        cout << root->data << " ";
        printInorder(root->right);
    }
}

int main() {
    Node* root = NULL;

    // Insert nodes into the BST
    insert(&root, 8);
    insert(&root, 3);
    insert(&root, 10);
    insert(&root, 1);
    insert(&root, 6);
    insert(&root, 14);
    insert(&root, 4);
    insert(&root, 7);
    insert(&root, 13);

    // Print the inorder traversal of the BST
    cout << "Inorder Traversal: ";
    printInorder(root);
    cout << endl;

    // Search for a node in the BST
    int data = 10;
    if (search(root, data))
        cout << data << " found in the BST" << endl;
    else
        cout << data << " not found in the BST" << endl;

    return 0;
}
```

This code creates a basic Binary Search Tree with insert and search operations. It also includes a function to print the inorder traversal of the tree, which can be useful for debugging purposes.

